# -*- coding: utf-8 -*-
"""data_extra_cards.py —— 速查工具新增内容的**文本源**。

本文件只放字符串，不做任何文件操作；由 add_cards.py 导入并写入
data_flow.js / data_guide.js。分成两个常量：

  FLOW_EXTRA  —— 追加到 STD_FLOW 的流程卡（每张 = 一个 {m:"流程" ...} 对象）
  GUIDE_EXTRA —— 追加到 STD_GUIDE 的引导向导（每张 = 一个 {m:"引导" ...} 对象）

引号规则：这些字符串会被直接写进 .js 文件，**字符串内部绝不能出现裸的半角
  双引号**。中文引号用全角 “ ”；代码示例里要显示半角引号必须转义。

所以下面每个字符串都用**普通三引号**（字符串前面不加 r）：普通三引号里反斜杠
  n 才是换行、反斜杠加半角引号才是半角引号，正是 .js 字符串需要的写法。
  若前面加了 r（原始字符串），反斜杠不参与转义，那个「反斜杠 + 半角引号」会被当成
  【反斜杠 + 字符串结束】，直接触发 SyntaxError: unexpected character after
  line continuation character。
"""

# ======================================================================
# 一、流程卡（data_flow.js）
# ======================================================================

FLOW_DAC = """
/* ===================== ⑮ DAC 模拟电压输出 ===================== */
{m:"流程", t:"flow", n:"⑮ DAC 模拟电压输出（12 位真模拟量，不是 PWM 滤波）",
 d:"PWM 是“方波”，DAC 是“真直流电压”。要输出 0~3.3V 连续变化（0-10V 变送器、模拟量给定、波形发生器）就得用 DAC。F407 只有 2 路：DAC1→PA4、DAC2→PA5。",
 f:[
  ["开时钟 + 配引脚","RCC_APB1Periph_DAC；PA4/PA5 必须配成 GPIO_Mode_AN（模拟），不是复用。"],
  ["先确认参考电压","VREF+ 接什么，满量程就是什么。多数板子接 VDDA=3.3V → 满量程 3.3V"],
  ["DAC_Init","填 DAC_Trigger（触发方式）、DAC_WaveGeneration（噪声/三角波）、DAC_OutputBuffer、DAC_LFSRUnmask/TriangleAmplitude"],
  ["DAC_Cmd + 给初值","DAC_Cmd(ENABLE) 后 DAC_SetChannel1Data(DAC_Align_12b_R, 初值)"],
  ["决定触发方式","软件触发最常用：DAC_Trigger_None；要严格等间隔就选 TIM 触发"],
  ["算电压数字量","value = 电压 / 3.3f * 4095.0f","12 位精度：1 个数 ≈ 0.806mV"],
  ["（进阶）用 DMA 出波形","TIM 触发 + DMA 循环搬到 DAC->DHR12R1，可输出任意波形"]
 ],
 a:[
  ["DAC1 / DAC2 引脚","PA4 / PA5","固定不可改，且与 SPI1_NSS、ADC12_IN4/5 冲突"],
  ["分辨率","12 位（0~4095）","1 个数字量 = 3.3V/4096 ≈ 0.806mV"],
  ["输出缓冲","DAC_OutputBuffer_Enable（默认）","使能后带载强，但输出最低只能到约 0.2V；要 0V 附近必须 Disable 并外加运放"],
  ["触发方式","DAC_Trigger_None（软件）/ TIMx_TRGO","软件触发随时改值；TIM 触发能严格等间隔（配 DMA 出波形）"],
  ["DAC_SoftwareTriggerCmd","DAC_Trigger_None 时也要调它一次才更新输出","很多人卡在这里：值写了、引脚不变，就是没触发"],
  ["板卡支持情况","板2 有 sys_dac.c；板1 没有","板1 要用就照本卡自己加"]
 ],
 e:"/* ============ DAC 输出 0~3.3V 模拟电压 ============ */\\n#include \"stm32f4xx.h\"\\n\\nvoid DAC1_Init(void)                      /* DAC1 -> PA4 */\\n{\\n    GPIO_InitTypeDef g;\\n    DAC_InitTypeDef  d;\\n\\n    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOA, ENABLE);\\n    RCC_APB1PeriphClockCmd(RCC_APB1Periph_DAC,   ENABLE);\\n\\n    /* 关键：DAC 引脚必须配成【模拟模式】，不是复用。\\n     *    若照 SPI/USART 的写法配成 GPIO_Mode_AF，引脚无输出。 */\\n    g.GPIO_Pin   = GPIO_Pin_4;\\n    g.GPIO_Mode  = GPIO_Mode_AN;          /* AN = analog，不是 AF */\\n    g.GPIO_OType = GPIO_OType_PP;         /* 模拟模式下这两项无意义 */\\n    g.GPIO_Speed = GPIO_Speed_100MHz;\\n    g.GPIO_PuPd  = GPIO_PuPd_NOPULL;      /* 模拟输入禁止上下拉 */\\n    GPIO_Init(GPIOA, &g);\\n\\n    d.DAC_Trigger          = DAC_Trigger_None;          /* 软件触发 */\\n    d.DAC_WaveGeneration   = DAC_WaveGeneration_None;    /* 无波形发生器 */\\n    d.DAC_LFSRUnmask_TriangleAmplitude = DAC_LFSRUnmask_Bit0;\\n    d.DAC_OutputBuffer     = DAC_OutputBuffer_Enable;    /* 开缓冲，带载强 */\\n    DAC_Init(DAC_Channel_1, &d);\\n\\n    DAC_Cmd(DAC_Channel_1, ENABLE);\\n    DAC_SetChannel1Data(DAC_Align_12b_R, 0);\\n}\\n\\n/* ---- 按电压值输出（0.0 ~ 3.3V） ---- */\\nvoid DAC1_SetVoltage(float v)\\n{\\n    uint16_t val;\\n\\n    if (v < 0.0f) { v = 0.0f; }\\n    if (v > 3.3f) { v = 3.3f; }\\n\\n    val = (uint16_t)(v / 3.3f * 4095.0f + 0.5f);\\n\\n    DAC_SetChannel1Data(DAC_Align_12b_R, val);\\n\\n    /* 软件触发模式下必须再调这一句，否则输出不更新。\\n     *    现象：“我明明写了值，万用表量还是 0V”。 */\\n    DAC_SoftwareTriggerCmd(DAC_Channel_1, ENABLE);\\n}\\n\\n/* ---- 按数字量输出（0 ~ 4095），不经过浮点，更快 ---- */\\nvoid DAC1_SetRaw(uint16_t val)\\n{\\n    if (val > 4095) { val = 4095; }\\n    DAC_SetChannel1Data(DAC_Align_12b_R, val);\\n    DAC_SoftwareTriggerCmd(DAC_Channel_1, ENABLE);\\n}\\n\\n/* 常见问题：\\n * 1) 引脚配成 GPIO_Mode_AF → 完全没有输出（必须是 GPIO_Mode_AN）\\n * 2) 忘了 DAC_SoftwareTriggerCmd → 值写了但引脚不变\\n * 3) 忘了 DAC_Cmd(ENABLE) → 同上\\n * 4) 开了 OutputBuffer 却想要 0V → 最低只能到约 0.2V\\n * 5) PA4 被 DAC 占用 → SPI1 的 NSS 就不能再用它（本项目 W25QXX 用软件 CS，正好避开）\\n */",
 r:"PA4 能输出 0~3.3V 连续可调电压，分辨率约 0.8mV；配 DMA + TIM 触发后能输出任意波形。",
 k:"DAC 模拟输出 电压 12位 PA4 PA5 数模转换 波形 三角波 噪声 DMA 触发 运放 0-10V 变送器 给定 DAC_SetChannel1Data DAC_SoftwareTriggerCmd DAC_Init DAC_Cmd 相关"},
"""

FLOW_CAN = """
/* ===================== ⑯ CAN 总线 ===================== */
{m:"流程", t:"flow", n:"⑯ CAN 总线通信（工业现场抗干扰首选）",
 d:"CAN 是双绞线差分 + 硬件 CRC + 自动重发的总线，比 RS485 抗干扰强得多，是工业现场的标准。F407 自带 CAN1(PD0/PD1) 与 CAN2(PB12/PB13)，外接一颗 TJA1050/SN65HVD230 收发器即可。",
 f:[
  ["接对线（最容易错）","CAN_H 接 CAN_H、CAN_L 接 CAN_L，两端各 120Ω 终端电阻；只能两端，中间节点加了会拉低阻抗"],
  ["开时钟 + 配引脚","CAN1：GPIOB/GPIOD + RCC_APB1Periph_CAN1；引脚 PD0/PD1（或重映射 PB8/PB9），复用推挽，速度至少 50MHz"],
  ["算波特率（核心难点）","CAN_Prescaler = APB1时钟 / (1 + BS1 + BS2) / 目标波特率；APB1=42MHz，500kbps 用 BS1=5Tq、BS2=6Tq、预分频=7"],
  ["CAN_Init","填 TTCM/ABOM/AWUM/NART/RFLM/TXFP/SJW/BS1/BS2/预分频；ABOM 一定要开，否则 Bus-Off 后上不了总线"],
  ["CAN_FilterInit","不配过滤器收到任何数据都不会进 FIFO。 这是 90% “CAN 收不到”的真正原因"],
  ["开中断 + NVIC","CAN_ITConfig(CAN1, CAN_IT_FMP0, ENABLE) + NVIC_Init(CAN1_RX0_IRQn)；优先级 ≥5"],
  ["发报文","填 CanTxMsg（StdId/DLC/Data）→ CAN_Transmit，用 CAN_TransmitStatus 查是否真发成功"],
  ["收报文","中断里 CAN_Receive(CAN1, CAN_FIFO0, &msg)"]
 ],
 a:[
  ["CAN1 引脚","PD0=CAN1_RX / PD1=CAN1_TX（或重映射到 PB8/PB9）","CAN2 用 PB12/PB13，需 CAN1 使能后 CAN2 才可用"],
  ["终端电阻","总线两端各 120Ω，中间节点不加","少一个 → 反射大；多一个 → 阻抗过低、距离骤降"],
  ["常用波特率","125k / 250k / 500k / 1M bps","本项目 APB1 = 42MHz"],
  ["500kbps 参数","CAN_Prescaler=7（42M/(1+5+6)/7 = 500k）","BS1=5Tq, BS2=6Tq, SJW=1Tq"],
  ["过滤器","必须配 CAN_FilterInit，否则 FIFO 永远空","想全收就把 Id 与 Mask 全部填 0"],
  ["ABOM 位","CAN_ABOM_Enable = 自动恢复总线","关掉的话 Bus-Off 后必须软件复位 CAN 才能恢复"],
  ["帧长","DLC 最大 8 字节","CAN 一帧就 8 字节，长数据要自己分包"],
  ["板2 现成封装","sys_can.c 的 SYS_CAN_*","SetSilentMode/LoopbackTest 会 DeInit+Init，过滤器与中断会被复位"]
 ],
 e:"/* ============ CAN1 初始化 + 收发（500kbps，APB1=42MHz） ============ */\\n#include \"stm32f4xx.h\"\\n\\nvoid CAN1_Init_500k(void)\\n{\\n    GPIO_InitTypeDef      g;\\n    CAN_InitTypeDef       c;\\n    CAN_FilterInitTypeDef cf;\\n    NVIC_InitTypeDef      ni;\\n\\n    RCC_AHB1PeriphClockCmd(RCC_AHB1Periph_GPIOD, ENABLE);\\n    RCC_APB1PeriphClockCmd(RCC_APB1Periph_CAN1,  ENABLE);\\n\\n    /* ---- 1. 引脚：PD0=RX / PD1=TX，复用推挽，速度至少 50MHz ---- */\\n    GPIO_PinAFConfig(GPIOD, GPIO_PinSource0, GPIO_AF_CAN1);\\n    GPIO_PinAFConfig(GPIOD, GPIO_PinSource1, GPIO_AF_CAN1);\\n    g.GPIO_Pin   = GPIO_Pin_0 | GPIO_Pin_1;\\n    g.GPIO_Mode  = GPIO_Mode_AF;\\n    g.GPIO_OType = GPIO_OType_PP;\\n    g.GPIO_Speed = GPIO_Speed_50MHz;\\n    g.GPIO_PuPd  = GPIO_PuPd_UP;\\n    GPIO_Init(GPIOD, &g);\\n\\n    /* ---- 2. 位时序：42MHz / (1+5+6) / 7预分频 = 500kbps ---- */\\n    c.CAN_TTCM = DISABLE;                  /* 时间触发模式：不用 */\\n    c.CAN_ABOM = ENABLE;                   /* 自动总线恢复：必须开。 */\\n    c.CAN_AWUM = DISABLE;                  /* 自动唤醒 */\\n    c.CAN_NART = DISABLE;                  /* 关掉 = 发送失败自动重发（工业场合要的） */\\n    c.CAN_RFLM = DISABLE;                  /* 溢出时覆盖旧报文 */\\n    c.CAN_TXFP = DISABLE;                  /* 按标识符优先级发 */\\n    c.CAN_Mode = CAN_Mode_Normal;          /* 回环测试用 CAN_Mode_LoopBack */\\n    c.CAN_SJW  = CAN_SJW_1tq;\\n    c.CAN_BS1  = CAN_BS1_5tq;\\n    c.CAN_BS2  = CAN_BS2_6tq;\\n    c.CAN_Prescaler = 7;                   /* 42M / (1+5+6) / 7 = 500k */\\n    CAN_Init(CAN1, &c);\\n\\n    /* ---- 3. 过滤器：不配它，FIFO 永远是空的。 ---- */\\n    cf.CAN_FilterNumber         = 0;\\n    cf.CAN_FilterMode           = CAN_FilterMode_IdMask;\\n    cf.CAN_FilterScale          = CAN_FilterScale_32bit;\\n    cf.CAN_FilterIdHigh         = 0x0000;   /* 全收：Id 与 Mask 都填 0 */\\n    cf.CAN_FilterIdLow          = 0x0000;\\n    cf.CAN_FilterMaskIdHigh     = 0x0000;\\n    cf.CAN_FilterMaskIdLow      = 0x0000;\\n    cf.CAN_FilterFIFOAssignment = CAN_Filter_FIFO0;\\n    cf.CAN_FilterActivation     = ENABLE;\\n    CAN_FilterInit(&cf);\\n\\n    /* ---- 4. FIFO0 收到报文就中断 ---- */\\n    CAN_ITConfig(CAN1, CAN_IT_FMP0, ENABLE);\\n\\n    ni.NVIC_IRQChannel                   = CAN1_RX0_IRQn;\\n    ni.NVIC_IRQChannelPreemptionPriority = 5;      /* FreeRTOS 红线 */\\n    ni.NVIC_IRQChannelSubPriority        = 0;\\n    ni.NVIC_IRQChannelCmd                = ENABLE;\\n    NVIC_Init(&ni);\\n}\\n\\n/* ---- 5. 发一帧（8 字节以内） ---- */\\nuint8_t CAN1_Send(uint32_t std_id, const uint8_t *data, uint8_t len)\\n{\\n    CanTxMsg tx;\\n    uint8_t  i;\\n\\n    if (len > 8) { len = 8; }              /* CAN 一帧最多 8 字节 */\\n\\n    tx.StdId = std_id;\\n    tx.ExtId = 0;\\n    tx.IDE   = CAN_Id_Standard;\\n    tx.RTR   = CAN_RTR_Data;\\n    tx.DLC   = len;\\n    for (i = 0; i < 8; i++) { tx.Data[i] = (i < len) ? data[i] : 0; }\\n\\n    if (CAN_Transmit(CAN1, &tx) == CAN_TxStatus_NoMailBox) { return 1; }\\n\\n    i = 0;\\n    while (CAN_TransmitStatus(CAN1, 0) == CAN_TxStatus_Pending && i < 100) { i++; delay_ms(1); }\\n\\n    return (CAN_TransmitStatus(CAN1, 0) == CAN_TxStatus_Ok) ? 0 : 2;\\n}\\n\\n/* ---- 6. 中断里收 ---- */\\nstatic volatile uint32_t g_can_rx_cnt = 0;\\nstatic uint8_t           g_can_last[8];\\n\\nvoid CAN1_RX0_IRQHandler(void)\\n{\\n    CanRxMsg rx;\\n    uint8_t  i;\\n\\n    if (CAN_GetITStatus(CAN1, CAN_IT_FMP0) != RESET)   /* FMP0 = FIFO 有待处理报文 */\\n    {\\n        CAN_Receive(CAN1, CAN_FIFO0, &rx);\\n        for (i = 0; i < 8; i++) { g_can_last[i] = rx.Data[i]; }\\n        g_can_rx_cnt++;\\n        /* FMP0 在 CAN_Receive 后由硬件自动更新，无需手动清 */\\n    }\\n}\\n\\n/* 常见问题（按出错频率排序）：\\n * 1) 没调 CAN_FilterInit → FIFO 永远空、中断永不触发。\\n *    现象：发送正常，但收不到任何报文。\\n * 2) CAN_ABOM = DISABLE → 一次错误风暴进了 Bus-Off 就彻底静默。\\n * 3) 波特率算错 → 其他节点全听不懂（ACK 错误 → 一直重发 → Bus-Off）。\\n *    500kbps 时一位 = 2µs，可用示波器量。\\n * 4) 终端电阻少了或多了 → 短距离能通、长距离时好时坏。\\n * 5) CAN_Mode_LoopBack 自发自收永远成功，不能当“通了”的证据。\\n *\\n * 本项目 FWLIB（板2）：sys_can.c 有 SYS_CAN_Init / SYS_CAN_Transmit /\\n *   SYS_CAN_SetCallback / SYS_CAN_SetSilentMode / SYS_CAN_LoopbackTest，\\n *   CAN1 引脚是 PA11/PA12（不是 PD0/PD1），波特率用枚举 SYS_CAN_500K。\\n *   已知问题：SetSilentMode 与 LoopbackTest 内部会 CAN_DeInit + CAN_Init，\\n *   过滤器配置和 CAN_ITConfig(FMP0) 会被一起清掉 → 调用后中断接收失效，\\n *   必须重新 CAN_FilterInit + CAN_ITConfig。\\n */",
 r:"两块板之间能用 CAN 收发 8 字节报文，500kbps，带自动总线恢复；总线出错后能自动回到正常通信。",
 k:"CAN CAN1 CAN2 总线 通信 工业 初始化 波特率 位时序 过滤器 Filter 收不到 中断 收发 500k 250k 125k TJA1050 SN65HVD230 差分 终端电阻 120欧 ABOM BusOff 相关 CAN_Init CAN_FilterInit CAN_Transmit CAN_Receive"},
"""

FLOW_RTC_ALARM = """
/* ===================== ⑰ RTC 闹钟与周期唤醒 ===================== */
{m:"流程", t:"flow", n:"⑰ RTC 闹钟 + 周期唤醒（到点自己动，不用主循环轮询）",
 d:"RTC 不只是“读时间”。它有两个能产生中断的功能：闹钟 ALARM（到某个时刻触发一次，如每天 8:00 上报）和周期唤醒 WAKEUP（每 N 秒触发一次，如每 10 秒采集）。有了它们，CPU 才能真去睡觉，功耗降一个数量级。",
 f:[
  ["先有 RTC 时钟","RTC 必须先初始化（LSE 32.768kHz 最准；无 LSE 时退 LSI）","LSE 起振要等，本工程有 3000ms 超时 + LSI 回退"],
  ["配闹钟值","填 RTC_AlarmTypeDef：RTC_AlarmTime（时/分/秒）+ RTC_AlarmMask 说明“哪几项不参与比较”"],
  ["RTC_SetAlarm + RTC_AlarmCmd","两步都要：SetAlarm 写值，AlarmCmd 才是总开关。只写值不开开关，闹钟永远不响"],
  ["配中断 + NVIC + EXTI","RTC_ITConfig(RTC_IT_ALRA) + NVIC_Init(RTC_Alarm_IRQn)；闹钟走 EXTI_Line17、唤醒走 EXTI_Line22，都要单独配 EXTI_Init"],
  ["写“每天固定时刻”的闹钟","RTC_AlarmMask 只屏蔽“日期”，时/分/秒都参与比较 → 每天同一时刻触发"],
  ["配周期唤醒","RTC_WakeUpClockConfig 选时钟源 + RTC_SetWakeUpCounter(period) + RTC_WakeUpCmd(ENABLE)"],
  ["中断里清标志","RTC_ClearITPendingBit(RTC_IT_ALRA/ALRB/WUT) 不清会反复进中断"]
 ],
 a:[
  ["闹钟通道","ALARM A / ALARM B 两个","可各设一个时刻，互不干扰"],
  ["RTC_AlarmMask","屏蔽项 = 不参与比较的字段","不屏蔽“日” → 那个日期每月只响一次；屏蔽了才是“每天”"],
  ["周期唤醒时钟","RTCCLK_Div16 → 2048Hz；Div2 → 16384Hz","查手册「RTC 唤醒定时器时钟」表算计数值"],
  ["EXTI 线","闹钟 = EXTI_Line17；唤醒 = EXTI_Line22","不配 EXTI 中断到不了 NVIC，这是最常漏的一步"],
  ["中断向量","RTC_Alarm_IRQn（ALARM A/B 与 WAKEUP 共用一个向量）","一个函数里要判三种标志"],
  ["写保护","改 RTC 寄存器前 RTC_WriteProtectionCmd(DISABLE)","不关写保护则写不进去，静默失败"],
  ["两板 API 差异","板1 是分开取时间；板2 是 SysRtc_t 结构体","两板 sys_rtc 是不同变体，不能整文件对拷"]
 ],
 e:"/* ============ RTC 闹钟 + 周期唤醒（中断驱动，主循环零轮询） ============ */\\n#include \"stm32f4xx.h\"\\n\\nstatic volatile uint8_t  g_alarm_fired = 0;\\nstatic volatile uint32_t g_wakeup_cnt  = 0;\\n\\n/* ------------------------------------------------------------------\\n * 1. 每天固定时刻的闹钟（例：每天 08:30:00 触发）\\n *    关键在 RTC_AlarmMask，屏蔽掉“日”，才会每天都响\\n * ------------------------------------------------------------------ */\\nvoid RTC_AlarmDaily_Init(uint8_t hour, uint8_t min, uint8_t sec)\\n{\\n    RTC_AlarmTypeDef alarm;\\n    NVIC_InitTypeDef ni;\\n    EXTI_InitTypeDef ex;\\n\\n    RTC_WriteProtectionCmd(DISABLE);              /* 改 RTC 寄存器前必须关写保护 */\\n\\n    alarm.RTC_AlarmTime.RTC_H12     = RTC_H12_AMPM;      /* 用 24 小时制就不看它 */\\n    alarm.RTC_AlarmTime.RTC_Hours   = hour;\\n    alarm.RTC_AlarmTime.RTC_Minutes = min;\\n    alarm.RTC_AlarmTime.RTC_Seconds = sec;\\n    alarm.RTC_AlarmMask = RTC_AlarmMask_DateWeekDay;      /* 屏蔽日期 → 每天 */\\n    alarm.RTC_AlarmDateWeekDaySel = RTC_AlarmDateWeekDaySel_Date;\\n    alarm.RTC_AlarmDateWeekDay = 1;\\n\\n    RTC_SetAlarm(RTC_Format_BIN, RTC_Alarm_A, &alarm);\\n\\n    RTC_AlarmCmd(RTC_Alarm_A, ENABLE);            /* 写了值还不够，必须开开关 */\\n\\n    RTC_ITConfig(RTC_IT_ALRA, ENABLE);            /* 中断使能 */\\n\\n    RTC_ClearFlag(RTC_FLAG_ALRAF);                /* 清历史标志，防开机就进中断 */\\n    RTC_WriteProtectionCmd(ENABLE);               /* 恢复写保护 */\\n\\n    ni.NVIC_IRQChannel                   = RTC_Alarm_IRQn;\\n    ni.NVIC_IRQChannelPreemptionPriority = 5;     /* FreeRTOS 红线 */\\n    ni.NVIC_IRQChannelSubPriority        = 0;\\n    ni.NVIC_IRQChannelCmd                = ENABLE;\\n    NVIC_Init(&ni);\\n\\n    EXTI_ClearITPendingBit(EXTI_Line17);          /* 闹钟走 EXTI17，必须清+配 */\\n    ex.EXTI_Line    = EXTI_Line17;\\n    ex.EXTI_Mode    = EXTI_Mode_Interrupt;\\n    ex.EXTI_Trigger = EXTI_Trigger_Rising;\\n    ex.EXTI_LineCmd = ENABLE;\\n    EXTI_Init(&ex);\\n}\\n\\n/* ------------------------------------------------------------------\\n * 2. 周期唤醒（例：每 1 秒进一次中断）\\n * ------------------------------------------------------------------ */\\nvoid RTC_WakeUp1s_Init(void)\\n{\\n    NVIC_InitTypeDef ni;\\n    EXTI_InitTypeDef ex;\\n\\n    RTC_WriteProtectionCmd(DISABLE);\\n\\n    /* 时钟源 RTCCLK/16：32768/16 = 2048Hz → 要 1 秒，计数值 = 2048 - 1 */\\n    RTC_WakeUpClockConfig(RTC_WakeUpClock_RTCCLK_Div16);\\n    RTC_SetWakeUpCounter(2047);\\n\\n    RTC_ClearFlag(RTC_FLAG_WUTF);\\n    RTC_ITConfig(RTC_IT_WUT, ENABLE);\\n\\n    RTC_WriteProtectionCmd(ENABLE);\\n    RTC_WakeUpCmd(ENABLE);                        /* 不使能就不计数 */\\n\\n    ni.NVIC_IRQChannel                   = RTC_Alarm_IRQn;   /* 和闹钟共用向量 */\\n    ni.NVIC_IRQChannelPreemptionPriority = 5;\\n    ni.NVIC_IRQChannelSubPriority        = 0;\\n    ni.NVIC_IRQChannelCmd                = ENABLE;\\n    NVIC_Init(&ni);\\n\\n    EXTI_ClearITPendingBit(EXTI_Line22);          /* 唤醒走 EXTI22 */\\n    ex.EXTI_Line    = EXTI_Line22;\\n    ex.EXTI_Mode    = EXTI_Mode_Interrupt;\\n    ex.EXTI_Trigger = EXTI_Trigger_Rising;\\n    ex.EXTI_LineCmd = ENABLE;\\n    EXTI_Init(&ex);\\n}\\n\\n/* ------------------------------------------------------------------\\n * 3. 共用中断：ALARM A / ALARM B / WAKEUP 三种标志都要判\\n * ------------------------------------------------------------------ */\\nvoid RTC_Alarm_IRQHandler(void)\\n{\\n    if (RTC_GetITStatus(RTC_IT_ALRA) != RESET)\\n    {\\n        RTC_ClearITPendingBit(RTC_IT_ALRA);       /* 不清会反复进 */\\n        EXTI_ClearITPendingBit(EXTI_Line17);\\n        g_alarm_fired = 1;\\n    }\\n    if (RTC_GetITStatus(RTC_IT_ALRB) != RESET)\\n    {\\n        RTC_ClearITPendingBit(RTC_IT_ALRB);\\n        EXTI_ClearITPendingBit(EXTI_Line17);\\n    }\\n    if (RTC_GetITStatus(RTC_IT_WUT) != RESET)\\n    {\\n        RTC_ClearITPendingBit(RTC_IT_WUT);\\n        EXTI_ClearITPendingBit(EXTI_Line22);\\n        g_wakeup_cnt++;\\n    }\\n}\\n\\n/* 常见问题：\\n * 1) 只调 RTC_SetAlarm 没调 RTC_AlarmCmd(ENABLE) → 闹钟永远不响。\\n * 2) RTC_AlarmMask 没屏蔽日期 → 会误认为“每天”，是“每月那一天”。\\n * 3) 忘了配 EXTI_Line17/22 → RTC 中断到不了 NVIC。\\n * 4) 改 RTC 寄存器没先 RTC_WriteProtectionCmd(DISABLE) → 写不进去，静默失败。\\n * 5) 备份域掉电（VBAT 没接电池）后时间与闹钟全丢 → 本工程用 BKP_DR0 魔数判首次上电。\\n *\\n * 本项目 FWLIB 已有封装：板1 sys_rtc.h 的 SYS_RTC_SetAlarmDaily /\\n *   SYS_RTC_SetAlarmCallback / SYS_RTC_WakeUp1sOn；\\n *   板2 的 sys_rtc.c 带 SYS_RTC_IsBackupValid（备份域掉电检测）。\\n */",
 r:"到点能自动触发中断：每天固定时刻上报、每 1 秒做一次采集，主循环完全不用轮询时间。",
 k:"RTC 闹钟 报警 ALARM 周期唤醒 WAKEUP 定时 中断 每天 固定时刻 秒中断 RTC_SetAlarm RTC_AlarmCmd RTC_SetWakeUpCounter RTC_WakeUpCmd EXTI17 EXTI22 写保护 备份域 低功耗 唤醒 相关"},
"""

# ======================================================================
# 二、引导向导（data_guide.js）
# 每步 = [标题, 为什么, 做什么, 代码, 怎么验证, 常见问题, 相关条目(空格分隔)]
